result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/validate.py", "content": "#!/usr/bin/env python3
"""Standalone validator for the proctored-exam scheduler.

Usage:
    python validate.py schedule_input.json assignments.json

Re-checks every rule against the raw input:
  * every exam is assigned exactly once, end - start == duration_minutes;
  * the exam sits entirely inside one availability window of its room;
  * room capacity >= enrolled_count;
  * no two exams in the same room overlap, with a mandatory 15-minute gap
    between consecutive exams in that room;
  * a proctor never covers two exams at once and never exceeds
    max_sessions_per_day within a single day (day = start // 1440).

Exit code 0 = all checks pass, 1 = violations found (reported on stdout).
"""

import json
import sys

GAP_MINUTES = 15
MINUTES_PER_DAY = 1440


def validate(indata, outdata):
    """Return a list of human-readable violation strings (empty if valid)."""
    errors = []
    exams = {e["id"]: e for e in indata["exams"]}
    rooms = {r["id"]: r for r in indata["rooms"]}
    proctors = {p["id"]: p for p in indata["proctors"]}

    if outdata.get("status") == "infeasible":
        return ["scheduler reported the instance as infeasible; "
                "no assignments to validate"]

    assignments = outdata.get("assignments")
    if not isinstance(assignments, list):
        return ["output has no 'assignments' list"]

    seen = {}
    for n, a in enumerate(assignments):
        label = f"assignment[{n}]"
        eid = a.get("exam")
        start, end = a.get("start"), a.get("end")
        rid, pid = a.get("room"), a.get("proctor")

        exam = exams.get(eid)
        if exam is None:
            errors.append(f"{label}: unknown exam id {eid!r}")
            continue
        if eid in seen:
            errors.append(f"{label}: exam {eid!r} assigned more than once")
            continue

        for name, val in (("start", start), ("end", end)):
            if not isinstance(val, int) or isinstance(val, bool):
                errors.append(f"{label}: {name} must be an integer, got {val!r}")
        if not (isinstance(start, int) and isinstance(end, int)):
            continue
        if start < 0 or end <= start:
            errors.append(f"{label}: invalid interval [{start}, {end})")
            continue
        if end - start != exam["duration_minutes"]:
            errors.append(
                f"exam {eid}: duration mismatch: end-start={end - start}, "
                f"expected {exam['duration_minutes']}")

        room = rooms.get(rid)
        if room is None:
            errors.append(f"exam {eid}: unknown room id {rid!r}")
        else:
            if room["capacity"] < exam["enrolled_count"]:
                errors.append(
                    f"exam {eid}: enrolled_count "
                    f"{exam['enrolled_count']} exceeds capacity "
                    f"{room['capacity']} of room {rid!r}")
            if not any(w[0] <= start and end <= w[1]
                       for w in room.get("windows", [])):
                errors.append(
                    f"exam {eid}: [{start}, {end}) not inside any window of "
                    f"room {rid!r}")
        seen[eid] = (rid, pid, start, end)

    missing = sorted(set(exams) - set(seen))
    if missing:
        errors.append(f"unassigned exams: {missing}")

    # Room exclusivity + mandatory gap.
    by_room = {}
    for eid, (rid, _pid, start, end) in seen.items():
        by_room.setdefault(rid, []).append((start, end, eid))
    for rid, items in by_room.items():
        items.sort()
        for (s1, e1, id1), (s2, e2, id2) in zip(items, items[1:]):
            if s2 < e1 + GAP_MINUTES:
                errors.append(
                    f"room {rid!r}: exams {id1!r} [end {e1}] and {id2!r} "
                    f"[start {s2}] overlap or lack the mandatory "
                    f"{GAP_MINUTES}-minute gap")

    # Proctor exclusivity + daily session limits.
    by_proctor = {}
    for eid, (_rid, pid, start, end) in seen.items():
        by_proctor.setdefault(pid, []).append((start, end, eid))
    for pid, items in by_proctor.items():
        if pid not in proctors:
            errors.append(f"unknown proctor id {pid!r} used for some exam(s)")
            continue
        items.sort()
        max_sessions = proctors[pid]["max_sessions_per_day"]
        days = {}
        for s1, e1, id1 in items:
            if s1 // MINUTES_PER_DAY == (e1 - 1) // MINUTES_PER_DAY:
                days[s1 // MINUTES_PER_DAY] = \
                    days.get(s1 // MINUTES_PER_DAY, 0) + 1
            else:  # exam crosses midnight: charge both days conservatively
                for d in (s1 // MINUTES_PER_DAY, (e1 - 1) // MINUTES_PER_DAY):
                    days[d] = days.get(d, 0) + 1
        for (s1, e1, id1), (s2, _e2, id2) in zip(items, items[1:]):
            if s2 < e1:
                errors.append(
                    f"proctor {pid!r}: exams {id1!r} and {id2!r} overlap "
                    f"([.., {e1}) vs [{s2}, ..))")
        for day, count in sorted(days.items()):
            if count > max_sessions:
                errors.append(
                    f"proctor {pid!r}: {count} sessions on day {day}, "
                    f"exceeds max_sessions_per_day={max_sessions}")

    return errors


def main(argv=None):
    argv = sys.argv[1:] if argv is None else argv
    if len(argv) != 2:
        print("usage: python validate.py <schedule_input.json> "
              "<assignments.json>", file=sys.stderr)
        return 2
    with open(argv[0]) as f:
        indata = json.load(f)
    with open(argv[1]) as f:
        outdata = json.load(f)
    errors = validate(indata, outdata)
    if errors:
        print("INVALID schedule:")
        for err in errors:
            print(f"  - {err}")
        return 1
    print("VALID schedule: all constraints satisfied.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
"})
